function prepareUmamiScope({ apiBaseUrl, websiteId, blog, timeZone }, anchor) {
  if (typeof apiBaseUrl !== 'string') throw new Error('Configure the canonical HTTPS API base of your self-hosted Umami instance.');
  const base = apiBaseUrl.trim().replace(/\/+$/u, '');
  const match = /^https:\/\/([^/?#\s]+)(\/[^?#\s]*)$/u.exec(base);
  if (!match || match[1].includes('@')) throw new Error('Use a canonical HTTPS Umami API base without credentials, query or fragment.');
  const authority = /^([^:]+)(?::([0-9]+))?$/u.exec(match[1]);
  if (!authority || authority[1].length > 253 || authority[1].split('.').some(part => !/^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/u.test(part))) throw new Error('The Umami API hostname is invalid.');
  if (authority[2] && (Number(authority[2]) < 1 || Number(authority[2]) > 65535)) throw new Error('The Umami API port is invalid.');
  if (!match[2].endsWith('/api') || match[2].split('/').slice(1).some(part => !/^[A-Za-z0-9._~-]+$/u.test(part) || part === '.' || part === '..')) throw new Error('Use the self-hosted API base ending in /api.');
  if (typeof websiteId !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/iu.test(websiteId.trim()) || /^0{8}-0{4}-0{4}-0{4}-0{12}$/u.test(websiteId.trim())) throw new Error('Configure the Umami website UUID.');
  if (typeof blog !== 'string' || !blog.trim()) throw new Error('Configure a site label.');
  if (typeof timeZone !== 'string' || !timeZone.trim()) throw new Error('Configure an IANA processing timezone.');
  const timezone = timeZone.trim(), date = new Date(anchor), endAt = date.getTime(), week = 7 * 24 * 60 * 60 * 1000;
  if (!Number.isSafeInteger(endAt) || endAt < week * 2) throw new Error('The captured report time is invalid.');
  let parts;
  try { parts = Object.fromEntries(new Intl.DateTimeFormat('en', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date).map(part => [part.type, part.value])); }
  catch { throw new Error('The processing timezone is invalid.'); }
  const id = websiteId.trim().toLowerCase(), endpoint = base + '/websites/' + id;
  return { apiBaseUrl: base, websiteId: id, blog: blog.trim(), timeZone: timezone, anchor: date.toISOString(), reportDate: parts.year + '-' + parts.month + '-' + parts.day,
    startAt: endAt - week, endAt, previousStartAt: endAt - week * 2, previousEndAt: endAt - week, statsUrl: endpoint + '/stats', metricsUrl: endpoint + '/metrics' };
}

const prepareClockScope = function prepareScope(input) {
  return prepareUmamiScope(input, new Date().toISOString());
}

