const prepare = function prepareUmamiSummary({ body, statusCode, blog, anchor, timeZone, startAt, endAt }) {
  if (statusCode !== 200 || !body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Umami did not return website summary statistics.');
  const names = ['pageviews', 'visitors', 'visits', 'bounces', 'totaltime'];
  const comparison = body.comparison;
  if (!comparison || typeof comparison !== 'object' || Array.isArray(comparison)) throw new Error('Umami 3.4.1 statistics must include the comparison object.');
  for (const metrics of [body, comparison]) for (const name of names) if (typeof metrics[name] !== 'number' || !Number.isFinite(metrics[name]) || metrics[name] < 0) throw new Error('Invalid Umami statistic: ' + name);
  const statistics = Object.fromEntries(names.map(name => [name, body[name]])), previous = Object.fromEntries(names.map(name => [name, comparison[name]]));
  const data = { site: blog, capturedAt: anchor, timezone: timeZone, period: { startAt, endAt, kind: 'rolling seven days; inclusive API timestamp bounds' }, statistics, comparison: previous,
    definitions: { pageviews: 'pageview count', visitors: 'unique visitor count', visits: 'visit count', bounces: 'single-page visits without a custom event', totaltime: 'total visit duration in seconds' } };
  return { statistics, comparison: previous, summaryData: JSON.stringify(data) };
}

