const prepare = function prepareUmamiPages({ currentBody, currentStatus, previousBody, previousStatus, blog, timeZone, startAt, endAt, previousStartAt, previousEndAt }) {
  if (currentStatus !== 200 || previousStatus !== 200 || !Array.isArray(currentBody) || !Array.isArray(previousBody)) throw new Error('Umami did not return both ranked page lists.');
  const validate = rows => {
    for (const row of rows) if (!row || typeof row !== 'object' || Array.isArray(row) || (row.x !== null && typeof row.x !== 'string') || typeof row.y !== 'number' || !Number.isFinite(row.y) || row.y < 0) throw new Error('Invalid Umami ranked page row.');
    return rows;
  };
  const current = validate(currentBody), previous = validate(previousBody);
  return { currentPages: current, previousPages: previous, pageData: JSON.stringify({ site: blog, timezone: timeZone,
    metric: 'Unique visitors by page path in the audited Umami 3.4.1 /metrics?type=path implementation; x is the page path, y the count. A null path is an unspecified dimension, not an invented URL.',
    scope: 'One ranked response per range, service default at most 500 rows; no pagination. Absence from a ranked response does not establish zero traffic.',
    current: { startAt, endAt, rows: current }, previous: { startAt: previousStartAt, endAt: previousEndAt, rows: previous } }) };
}

