const prepare = function prepareUmamiRow({ summary, pagesReport, reportDate, blog }) {
  for (const [name, value] of Object.entries({ summary, pagesReport })) if (typeof value !== 'string' || !value.trim()) throw new Error('The ' + name + ' analysis did not return nonempty text.');
  if (!/^\d{4}-\d{2}-\d{2}$/u.test(reportDate) || typeof blog !== 'string' || !blog.trim()) throw new Error('The report date or site label is invalid.');
  return { row: { Date: reportDate, Summary: summary, 'Top pages': pagesReport, 'Blog name': blog } };
}

