const confirm = function confirmUmamiReport({ row }) {
  if (!row || typeof row !== 'object' || Array.isArray(row) || !Number.isInteger(row.id) || row.id <= 0) throw new Error('Baserow did not confirm a created report row ID.');
  return { row };
